# The key insight: it's just "replace 3->0, replace 5->3"
# Let me verify this rule works
def simple_transform(grid):
    bg = grid[0][0]  # 3
    result = []
    for row in grid:
        new_row = []
        for cell in row:
            if cell == bg:
                new_row.append(0)
            else:
                new_row.append(3)
        result.append(new_row)
    return result

result = simple_transform(correct_demo_input)
print(f"\nTransform matches: {result == correct_demo_output}")

